namespace sv_582bfc7e9c244eddbc85e8e95f5f1101.Services;

public class WarehouseInfo
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped service (per-circuit) that holds the currently selected warehouse
/// and notifies subscribers when it changes.
/// </summary>
public class WarehouseStateService
{
    private static readonly List<WarehouseInfo> AllWarehouses =
    [
        new() { Id = "WH-001", Name = "Warehouse A — Downtown" },
        new() { Id = "WH-002", Name = "Warehouse B — Airport" },
        new() { Id = "WH-003", Name = "Warehouse C — Harbor" },
    ];

    public IReadOnlyList<WarehouseInfo> Warehouses => AllWarehouses;

    public WarehouseInfo CurrentWarehouse { get; private set; } = AllWarehouses[0];

    public event Func<Task>? OnChange;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        var warehouse = AllWarehouses.FirstOrDefault(w => w.Id == warehouseId);
        if (warehouse is null || warehouse.Id == CurrentWarehouse.Id)
            return;

        CurrentWarehouse = warehouse;

        if (OnChange is not null)
            await OnChange.Invoke();
    }
}

namespace sv_582bfc7e9c244eddbc85e8e95f5f1101.Services;

/// <summary>
/// Scoped service (per-circuit) that polls for low-stock alerts and notifies
/// all subscribed components when new data arrives.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _activeSubscribers;

    public int LowStockCount { get; private set; }

    /// <summary>
    /// Fired on the polling thread when new alert data is available.
    /// All subscribed components should call InvokeAsync(StateHasChanged) in their handler.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChangedAsync;
    }

    /// <summary>Simulates a database query returning a random low-stock count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component that needs polling becomes active.
    /// Starts the timer on the first subscriber.
    /// </summary>
    public void StartPolling()
    {
        _activeSubscribers++;
        if (_activeSubscribers == 1)
            StartTimer();
    }

    /// <summary>
    /// Call when a component that needs polling is disposed.
    /// Stops the timer when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        _activeSubscribers = Math.Max(0, _activeSubscribers - 1);
        if (_activeSubscribers == 0)
            StopTimer();
    }

    private void StartTimer()
    {
        StopTimer();
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopTimer()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start, then every 10 seconds.
        await RefreshAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
                    break;
                await RefreshAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task RefreshAsync()
    {
        LowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouse.Id);

        if (OnAlertCountChanged is not null)
            await OnAlertCountChanged.Invoke();
    }

    private async Task HandleWarehouseChangedAsync()
    {
        // When the warehouse changes, immediately refresh the count
        // so every subscriber sees updated data for the new warehouse.
        if (_activeSubscribers > 0)
            await RefreshAsync();
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChangedAsync;
        StopTimer();
    }
}

