@using sv_582bfc7e9c244eddbc85e8e95f5f1101.Services
@implements IDisposable
@inject WarehouseStateService WarehouseState

<select class="form-select form-select-sm" value="@WarehouseState.CurrentWarehouse.Id"
        @onchange="OnWarehouseSelected">
    @foreach (var wh in WarehouseState.Warehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
    }

    private async Task OnWarehouseSelected(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
            await WarehouseState.SetWarehouseAsync(id);
    }

    private async Task HandleStateChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
    }
}

